"""Tests for source-root path expansion."""

from pathlib import Path

import pytest

from pylint.config.argument import _paths_csv_transformer


@pytest.mark.parametrize(
    "pattern",
    ["src/*", "src/package?", "src/package[12]", "**/package?"],
)
def test_source_roots_glob(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, pattern: str
) -> None:
    monkeypatch.chdir(tmp_path)
    for name in ("package1", "package2"):
        (tmp_path / "src" / name).mkdir(parents=True)
    assert set(_paths_csv_transformer(pattern)) == {
        str(Path("src/package1")),
        str(Path("src/package2")),
    }


@pytest.mark.parametrize("prefix", ["~", "$SOURCE_ROOTS_TEST", "absolute"])
def test_source_roots_expansion_before_globbing(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, prefix: str
) -> None:
    monkeypatch.setenv("HOME", str(tmp_path))
    monkeypatch.setenv("USERPROFILE", str(tmp_path))
    monkeypatch.setenv("SOURCE_ROOTS_TEST", str(tmp_path))
    root = tmp_path / "src" / "package1"
    root.mkdir(parents=True)
    if prefix == "absolute":
        prefix = str(tmp_path)
    assert _paths_csv_transformer(f"{prefix}/src/*") == [str(root)]


def test_source_roots_mixed_paths(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "src" / "package1").mkdir(parents=True)
    (tmp_path / "explicit").mkdir()
    assert _paths_csv_transformer("explicit, src/*, missing") == [
        "explicit",
        str(Path("src/package1")),
        "missing",
    ]
    assert _paths_csv_transformer("src/unmatched*, explicit") == ["explicit"]
    assert _paths_csv_transformer("") == []

